        "The name this field's value is stored under on every document of this kind. Choose it once and leave it alone: renaming it here does not move the values already recorded, so the old ones become unreachable.": "Το όνομα με το οποίο αποθηκεύεται η τιμή του πεδίου σε κάθε έγγραφο αυτού του είδους. Επιλέξτε το μία φορά και μην το αλλάξετε: η μετονομασία εδώ δεν μεταφέρει τις ήδη καταχωρισμένες τιμές, οπότε οι παλιές γίνονται απρόσιτες.",
        "The values of the fields the document type declares.": "Οι τιμές των πεδίων που ορίζει ο τύπος εγγράφου.",
        "Tick this to make the field compulsory: the details of a document of this kind cannot be saved while it is left empty.": "Επιλέξτε το για να γίνει το πεδίο υποχρεωτικό: οι λεπτομέρειες ενός εγγράφου αυτού του είδους δεν αποθηκεύονται όσο είναι κενό.",
