        "The case number, such as Z-2026-00412.": "Ο αριθμός της υπόθεσης, για παράδειγμα Z-2026-00412.",
        "The case this agenda item belongs to in the organisation's case system: its address, its case number and its title. Set by linking the item to a case; decidiq reads the case once to fill the title.": "Η υπόθεση στην οποία ανήκει αυτό το θέμα ημερήσιας διάταξης στο σύστημα υποθέσεων του οργανισμού: η διεύθυνση, ο αριθμός και ο τίτλος της. Ορίζεται με τη σύνδεση του θέματος με μια υπόθεση· το decidiq διαβάζει την υπόθεση μία φορά για να συμπληρώσει τον τίτλο.",
        "The confidentiality ground it was sent with.": "Ο λόγος εμπιστευτικότητας με τον οποίο στάλθηκε.",
        "The document was sent marked confidential.": "Το έγγραφο στάλθηκε ως εμπιστευτικό.",
