        "The Nextcloud account of the member who subscribes. Empty for a resident.": "Ο λογαριασμός Nextcloud του μέλους που εγγράφεται. Κενό για κάτοικο.",
        "Resident": "Κάτοικος",
        "The portal subject reference of the resident who subscribes. Empty for a member. decidiq never stores a resident's email address.": "Η αναφορά πύλης του κατοίκου που εγγράφεται. Κενό για μέλος. Το decidiq δεν αποθηκεύει ποτέ τη διεύθυνση email κατοίκου.",
        "The bodies to follow. Empty means every body.": "Τα όργανα προς παρακολούθηση. Κενό σημαίνει όλα τα όργανα.",
        "What to follow": "Τι παρακολουθείται",
        "Agendas, papers, decisions and minutes, one or more.": "Ημερήσιες διατάξεις, έγγραφα, αποφάσεις και πρακτικά, ένα ή περισσότερα.",
        "Immediately (after a short wait that groups an editing session), a daily digest at 07:00, or a weekly digest on Monday at 07:00.": "Αμέσως (μετά από σύντομη αναμονή που ομαδοποιεί μια επεξεργασία), ημερήσια σύνοψη στις 07:00 ή εβδομαδιαία τη Δευτέρα στις 07:00.",
        "Unsubscribing switches this off.": "Η απεγγραφή το απενεργοποιεί.",
        "Last sent": "Τελευταία αποστολή",
        "When the subscriber last received a message. Set by the digest job.": "Πότε ο συνδρομητής έλαβε τελευταία μήνυμα. Ορίζεται από την εργασία σύνοψης.",
        "Publication event": "Συμβάν δημοσίευσης",
        "What happened to: an agenda, a paper, a decision or minutes.": "Σε τι αφορά: ημερήσια διάταξη, έγγραφο, απόφαση ή πρακτικά.",
        "The body the agenda, paper, decision or minutes belongs to.": "Το όργανο στο οποίο ανήκει η ημερήσια διάταξη, το έγγραφο, η απόφαση ή τα πρακτικά.",
        "The meeting it belongs to, when there is one.": "Η συνεδρίαση στην οποία ανήκει, αν υπάρχει.",
        "The schema of the object the event is about, such as meeting, agenda-item or decision.": "Το σχήμα του αντικειμένου του συμβάντος, όπως meeting, agenda-item ή decision.",
        "Object": "Αντικείμενο",
        "The object the event is about. The digest checks the subscriber may read it before sending.": "Το αντικείμενο του συμβάντος. Η σύνοψη ελέγχει ότι ο συνδρομητής μπορεί να το διαβάσει πριν την αποστολή.",
        "The meeting, paper, decision or minutes title.": "Ο τίτλος της συνεδρίασης, του εγγράφου, της απόφασης ή των πρακτικών.",
        "Summary": "Σύνοψη",
        "One line on what happened, such as: Agenda changed: item 4 added.": "Μία γραμμή για το τι συνέβη, π.χ.: Η ημερήσια διάταξη άλλαξε: προστέθηκε το θέμα 4.",
        "Whether residents may hear of it: only publicly published agendas, decisions and minutes count.": "Αν οι κάτοικοι μπορούν να το μάθουν: μετρούν μόνο δημόσια δημοσιευμένες διατάξεις, αποφάσεις και πρακτικά.",
        "Happened at": "Συνέβη στις",
        "When it was published or changed.": "Πότε δημοσιεύτηκε ή άλλαξε.",
        "Other": "Άλλο",
