        "%d updates from the bodies you follow": "%d ενημερώσεις από τα όργανα που ακολουθείτε",
        "About": "Σχετικά",
        "Could not load memberships": "Δεν ήταν δυνατή η φόρτωση των συμμετοχών",
        "Could not load the voting record": "Δεν ήταν δυνατή η φόρτωση του ιστορικού ψηφοφοριών",
        "Earlier memberships ({count})": "Προηγούμενες συμμετοχές ({count})",
