        "Copied from the step at instantiation so the stage can resolve its own actor when it becomes live. The rule lives on the stage and not only on the route because editing a route must never change a stage already in flight (REQ-AR-012).": "Αντιγράφεται από το βήμα κατά τη δημιουργία, ώστε το στάδιο να μπορεί να ορίσει τον δικό του υπεύθυνο όταν ενεργοποιηθεί. Ο κανόνας βρίσκεται στο στάδιο και όχι μόνο στη διαδρομή, επειδή η επεξεργασία μιας διαδρομής δεν πρέπει ποτέ να αλλάζει ένα στάδιο που βρίσκεται ήδη σε εξέλιξη (REQ-AR-012).",
        "Copied from the step at instantiation, so editing a route never changes what the silence of a stage already in flight means.": "Αντιγράφεται από το βήμα κατά τη δημιουργία, ώστε η επεξεργασία μιας διαδρομής να μην αλλάζει ποτέ τι σημαίνει η σιωπή ενός σταδίου που βρίσκεται ήδη σε εξέλιξη.",
        "Corporate (corp)": "Εταιρικό (corp)",
        "Corporate-governance extension (beyond Popolo, MCCG): board-member independence, mode=corp. NOT the same question as `external`, which records whether the member sits from outside the administrative organ. A member can be external and non-independent, or internal and independent; neither value is derivable from the other.": "Επέκταση εταιρικής διακυβέρνησης (πέρα από το Popolo, MCCG): ανεξαρτησία μέλους συμβουλίου, mode=corp. ΔΕΝ είναι το ίδιο ερώτημα με το `external`, που καταγράφει αν το μέλος προέρχεται από έξω από το διοικητικό όργανο. Ένα μέλος μπορεί να είναι εξωτερικό και μη ανεξάρτητο ή εσωτερικό και ανεξάρτητο. Καμία τιμή δεν προκύπτει από την άλλη.",
        "Could not approve the reaction": "Αδύνατη η έγκριση της αντίδρασης",
        "Could not attach the recording.": "Αδύνατη η επισύναψη της ηχογράφησης.",
