        "Could not submit your reaction": "Αδύνατη η υποβολή της αντίδρασής σας",
        "Could not update status.": "Αδύνατη η ενημέρωση κατάστασης.",
        "Council information letter": "Ενημερωτική επιστολή προς το συμβούλιο",
        "Council proposal": "Εισήγηση προς το συμβούλιο",
        "Council registry": "Μητρώο συμβουλίου",
        "Council turnover batch": "Παρτίδα ανανέωσης συμβουλίου",
        "Count": "Πλήθος",
        "Counts of the current members, without names. Age bands are worked out today.": "Αριθμοί των τρεχόντων μελών, χωρίς ονόματα. Οι ηλικιακές ομάδες υπολογίζονται με βάση τη σημερινή ημερομηνία.",
        "Counts only": "Μόνο αριθμοί",
        "Create meeting": "Δημιουργία συνεδρίασης",
        "Create proposal for this object": "Δημιουργία πρότασης για αυτό το αντικείμενο",
        "Cycle step": "Βήμα κύκλου",
        "Date after which this type may no longer be used. Empty means indefinitely.": "Ημερομηνία μετά την οποία αυτός ο τύπος δεν μπορεί πλέον να χρησιμοποιηθεί. Κενό σημαίνει επ' αόριστον.",
        "Date from which this type may be used.": "Ημερομηνία από την οποία μπορεί να χρησιμοποιηθεί αυτός ο τύπος.",
        "Date the membership ends. The end-membership step sets Membership.endDate to this value.": "Ημερομηνία λήξης της συμμετοχής. Το βήμα λήξης συμμετοχής ορίζει το Membership.endDate σε αυτή την τιμή.",
        "Date the person was formally installed. Completing the installation step requires this, installationType and installationMeeting.": "Ημερομηνία κατά την οποία το πρόσωπο ορκίστηκε επίσημα. Η ολοκλήρωση του βήματος ορκωμοσίας απαιτεί αυτή, το installationType και το installationMeeting.",
        "Days after approval": "Ημέρες μετά την έγκριση",
        "De datum waarop het besluit is gepubliceerd. Onderscheiden van `publishedAt`, dat het moment van publiceren in dit systeem vastlegt; dit is de datum die het besluit zelf draagt. BRC `publicatiedatum`.": "Η ημερομηνία κατά την οποία δημοσιεύτηκε η απόφαση. Διαφέρει από το `publishedAt`, που καταγράφει τη στιγμή δημοσίευσης σε αυτό το σύστημα. Αυτή είναι η ημερομηνία που φέρει η ίδια η απόφαση. BRC `publicatiedatum`.",
        "De datum waarop het besluit is verzonden aan de belanghebbende. BRC `verzenddatum`.": "Η ημερομηνία κατά την οποία η απόφαση στάλθηκε στον ενδιαφερόμενο. BRC `verzenddatum`.",
        "De datum waarop het besluit vervalt. Onderscheiden van `effectiveDate`, die zegt wanneer het ingaat. BRC `vervaldatum`.": "Η ημερομηνία κατά την οποία η απόφαση λήγει. Διαφέρει από το `effectiveDate`, που δηλώνει πότε τίθεται σε ισχύ. BRC `vervaldatum`.",
        "Deadline reminder sent at": "Η υπενθύμιση προθεσμίας στάλθηκε στις",
        "Deadline {date}": "Προθεσμία {date}",
        "Death": "Θάνατος",
        "Decided by": "Αποφασίστηκε από",
        "Decision list": "Λίστα αποφάσεων",
        "Decision maker": "Υπεύθυνος λήψης απόφασης",
        "Decision outcome recorded when status=decided. Null when status is pending/active/skipped. `returned` is the sign-off case and behaves unlike the rest: it re-opens an EARLIER stage rather than ending this one, which is why `rejected` and `deferred` could not express it, both end a stage and neither reopens one.": "Το αποτέλεσμα της απόφασης καταγράφεται όταν status=decided. Null όταν το status είναι pending/active/skipped. Το `returned` είναι η περίπτωση υπογραφής και συμπεριφέρεται διαφορετικά από τα υπόλοιπα: ξανανοίγει ένα ΠΡΟΗΓΟΥΜΕΝΟ στάδιο αντί να τερματίζει αυτό, γι' αυτό τα `rejected` και `deferred` δεν μπορούσαν να το εκφράσουν, αφού και τα δύο τερματίζουν ένα στάδιο και κανένα δεν ξανανοίγει κάποιο.",
        "Decision policy": "Πολιτική απόφασης",
