        "Each Office paper on this agenda item with the PDF made of it, or why no PDF was made. Written by decidiq, not by hand.": "Κάθε έγγραφο Office σε αυτό το θέμα ημερήσιας διάταξης με το PDF που δημιουργήθηκε από αυτό, ή γιατί δεν δημιουργήθηκε PDF. Γράφεται από το decidiq, όχι χειροκίνητα.",
        "Each Office paper on this meeting with the PDF made of it, or why no PDF was made. Written by decidiq, not by hand.": "Κάθε έγγραφο Office σε αυτή τη συνεδρίαση με το PDF που δημιουργήθηκε από αυτό, ή γιατί δεν δημιουργήθηκε PDF. Γράφεται από το decidiq, όχι χειροκίνητα.",
