        "Every adopted amendment worked into this motion, with the text before and after.": "Κάθε εγκεκριμένη τροπολογία που ενσωματώθηκε σε αυτή την πρόταση, με το κείμενο πριν και μετά.",
        "Every published version of the agenda, with the items it held.": "Κάθε δημοσιευμένη έκδοση της ημερήσιας διάταξης, με τα θέματα που περιείχε.",
