        "Rectify…": "Διόρθωση…",
        "Reference to the Meeting where the person was installed. The meeting itself is owned elsewhere and only linked here.": "Αναφορά στη Συνεδρίαση όπου ορκίστηκε το πρόσωπο. Η ίδια η συνεδρίαση ανήκει αλλού και απλώς συνδέεται εδώ.",
        "Reference to the Membership created as an outcome. Optional until created: an intake often onboards a person before the membership row exists.": "Αναφορά στη Συμμετοχή που δημιουργήθηκε ως αποτέλεσμα. Προαιρετική μέχρι να δημιουργηθεί: μια εισαγωγή συχνά εντάσσει ένα πρόσωπο πριν υπάρξει η εγγραφή συμμετοχής.",
        "Reference to the Membership to be end-dated. Required. End-dating happens on the end-membership step, never as an automatic side effect.": "Αναφορά στη Συμμετοχή που πρέπει να λάβει ημερομηνία λήξης. Υποχρεωτική. Ο ορισμός ημερομηνίας λήξης γίνεται στο βήμα λήξης συμμετοχής, ποτέ ως αυτόματη παρενέργεια.",
        "Reference to the governance body the person is joining. Required. With targetRole it derives the body-role group mapping the assign-groups step uses.": "Αναφορά στον φορέα διακυβέρνησης στον οποίο εντάσσεται το πρόσωπο. Υποχρεωτική. Μαζί με το targetRole παράγει την αντιστοίχιση οργάνου-ρόλου σε ομάδα που χρησιμοποιεί το βήμα ανάθεσης ομάδων.",
        "Reference to the governance body the person is leaving. Required. With the person's role it derives the body-role group mapping the revoke-groups step uses.": "Αναφορά στον φορέα διακυβέρνησης από τον οποίο αποχωρεί το πρόσωπο. Υποχρεωτική. Μαζί με τον ρόλο του προσώπου παράγει την αντιστοίχιση οργάνου-ρόλου σε ομάδα που χρησιμοποιεί το βήμα ανάκλησης ομάδων.",
