        "Withdraw reason": "Λόγος ανάκλησης",
        "Withdrawing removes the published record from the public surface and retracts the OpenCatalogi publication. A reason is required and recorded in the audit trail (WOO correction duty).": "Η ανάκληση αφαιρεί τη δημοσιευμένη εγγραφή από τη δημόσια επιφάνεια και αποσύρει τη δημοσίευση από το OpenCatalogi. Απαιτείται λόγος, ο οποίος καταγράφεται στο ίχνος ελέγχου (υποχρέωση διόρθωσης κατά τον WOO).",
        "Withdrawn reason": "Λόγος ανάκλησης",
