        "Paper summary": "Σύνοψη εγγράφου",
        "Paper title": "Τίτλος εγγράφου",
        "Summarised in parts": "Συνοψίστηκε σε μέρη",
        "The AI output in markdown, then the clerk's edit of it.": "Η έξοδος της AI σε markdown και έπειτα η επεξεργασία της από τον υπάλληλο.",
        "The Nextcloud file id of the paper (schema:isBasedOn).": "Το αναγνωριστικό αρχείου Nextcloud του εγγράφου (schema:isBasedOn).",
        "The Nextcloud file id of the second paper of a comparison.": "Το αναγνωριστικό αρχείου Nextcloud του δεύτερου εγγράφου μιας σύγκρισης.",
        "The TaskProcessing provider that wrote the text, for provenance.": "Ο πάροχος TaskProcessing που έγραψε το κείμενο, για την προέλευση.",
        "The TaskProcessing task that writes the text.": "Η εργασία TaskProcessing που γράφει το κείμενο.",
        "The agenda item the paper is attached to.": "Το θέμα ημερήσιας διάταξης στο οποίο είναι συνημμένο το έγγραφο.",
        "The display name of the clerk who last showed or hid the summary, as the label shows it.": "Το εμφανιζόμενο όνομα του υπαλλήλου που τελευταίος εμφάνισε ή απέκρυψε τη σύνοψη, όπως το δείχνει η ετικέτα.",
        "The file name of the paper when the summary was asked for.": "Το όνομα αρχείου του εγγράφου όταν ζητήθηκε η σύνοψη.",
        "The file name of the second paper of a comparison.": "Το όνομα αρχείου του δεύτερου εγγράφου μιας σύγκρισης.",
        "The provider's error message when the task failed.": "Το μήνυμα σφάλματος του παρόχου όταν η εργασία απέτυχε.",
        "True when the paper was too long for one task and was summarised part by part.": "True όταν το έγγραφο ήταν πολύ μεγάλο για μία εργασία και συνοψίστηκε κατά μέρη.",
        "When the clerk last showed or hid the summary.": "Πότε ο υπάλληλος εμφάνισε ή απέκρυψε τελευταία φορά τη σύνοψη.",
        "requested until the AI answers, then draft or failed; a clerk shows a draft to members or hides it.": "requested μέχρι να απαντήσει η AI, έπειτα draft ή failed. Ένας υπάλληλος εμφανίζει ένα προσχέδιο στα μέλη ή το αποκρύπτει.",
        "AI-generated summary, checked by {name} on {date}": "Σύνοψη από AI, ελέγχθηκε από {name} στις {date}",
        "Asked the AI provider. The summary appears here as a draft when it is ready.": "Ζητήθηκε από τον πάροχο AI. Η σύνοψη εμφανίζεται εδώ ως προσχέδιο όταν είναι έτοιμη.",
        "Compare with": "Σύγκριση με",
        "Compare {name} with another paper": "Σύγκριση του {name} με άλλο έγγραφο",
        "Comparison of {paper} with {other}": "Σύγκριση του {paper} με το {other}",
        "Hidden": "Κρυφό",
        "No AI provider is installed, so papers cannot be summarised.": "Δεν είναι εγκατεστημένος πάροχος AI, οπότε τα έγγραφα δεν μπορούν να συνοψιστούν.",
        "No summaries of the papers yet.": "Δεν υπάρχουν ακόμη συνόψεις των εγγράφων.",
        "Requested": "Ζητήθηκε",
        "Show to members": "Εμφάνιση στα μέλη",
