        "Summary of {paper}": "Σύνοψη του {paper}",
        "Summary text": "Κείμενο σύνοψης",
        "The AI provider could not write it: {reason}": "Ο πάροχος AI δεν μπόρεσε να τη γράψει: {reason}",
        "The paper was long, so it was summarised in parts first.": "Το έγγραφο ήταν μεγάλο, οπότε συνοψίστηκε πρώτα κατά μέρη.",
        "The summaries of this agenda item could not be read.": "Οι συνόψεις αυτού του θέματος ημερήσιας διάταξης δεν μπόρεσαν να διαβαστούν.",
        "The summary could not be asked for.": "Η σύνοψη δεν μπόρεσε να ζητηθεί.",
        "The summary could not be saved.": "Η σύνοψη δεν μπόρεσε να αποθηκευτεί.",
        "Waiting for the AI provider. Reload the page in a few minutes.": "Αναμονή για τον πάροχο AI. Ανανεώστε τη σελίδα σε λίγα λεπτά.",
        "Summaries of the papers": "Συνόψεις των εγγράφων",
        "Meeting broadcast": "Μετάδοση συνεδρίασης",
        "A public livestream of a meeting: its status, the player and recording addresses, the broadcast parts and the released captions. Readable without an account once its publication date has passed.": "Μια δημόσια ζωντανή μετάδοση μιας συνεδρίασης: η κατάστασή της, οι διευθύνσεις του προγράμματος αναπαραγωγής και της εγγραφής, τα μέρη της μετάδοσης και οι υπότιτλοι που δημοσιεύτηκαν. Μπορεί να διαβαστεί χωρίς λογαριασμό μόλις περάσει η ημερομηνία δημοσίευσής της.",
        "The meeting this broadcast shows; one broadcast per meeting.": "Η συνεδρίαση που δείχνει αυτή η μετάδοση. Μία μετάδοση ανά συνεδρίαση.",
        "The meeting's title, copied when the broadcast is made, so the public row needs no private meeting.": "Ο τίτλος της συνεδρίασης, αντιγράφεται όταν δημιουργείται η μετάδοση, ώστε η δημόσια γραμμή να μη χρειάζεται ιδιωτική συνεδρίαση.",
        "The name of the body that meets, copied when the broadcast is made.": "Το όνομα του οργάνου που συνεδριάζει, αντιγράφεται όταν δημιουργείται η μετάδοση.",
        "When the meeting starts, copied when the broadcast is made.": "Πότε ξεκινά η συνεδρίαση, αντιγράφεται όταν δημιουργείται η μετάδοση.",
        "planned until a clerk tests or goes live; a test ends back in planned; live and paused alternate until the broadcast ends.": "planned μέχρι ένας υπάλληλος να κάνει δοκιμή ή να βγει ζωντανά. Μια δοκιμή επιστρέφει σε planned. Τα live και paused εναλλάσσονται μέχρι να λήξει η μετάδοση.",
        "Preview address": "Διεύθυνση προεπισκόπησης",
        "The staff preview of a test. Never shown on the portal.": "Η προεπισκόπηση μιας δοκιμής για το προσωπικό. Δεν εμφανίζεται ποτέ στην πύλη.",
        "Player address": "Διεύθυνση προγράμματος αναπαραγωγής",
        "The public player, written when the broadcast goes live.": "Το δημόσιο πρόγραμμα αναπαραγωγής, γράφεται όταν η μετάδοση βγαίνει ζωντανά.",
        "Recording address": "Διεύθυνση εγγραφής",
        "The streaming service's public recording, written after the broadcast ended.": "Η δημόσια εγγραφή της υπηρεσίας ροής, γράφεται μετά τη λήξη της μετάδοσης.",
        "Tested at": "Δοκιμάστηκε στις",
        "When the last test ran.": "Πότε έγινε η τελευταία δοκιμή.",
        "Tested by": "Δοκιμάστηκε από",
        "Who ran the last test.": "Ποιος έκανε την τελευταία δοκιμή.",
        "Test result": "Αποτέλεσμα δοκιμής",
        "What the clerk found in the last test.": "Τι διαπίστωσε ο υπάλληλος στην τελευταία δοκιμή.",
        "Test note": "Σημείωση δοκιμής",
        "The clerk's note on the last test.": "Η σημείωση του υπαλλήλου για την τελευταία δοκιμή.",
        "Live captions": "Ζωντανοί υπότιτλοι",
